  {
    const esc=x=>String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;');
    const tbl=rows=>'<table style="border-collapse:collapse;font-size:12.5px;margin:4px 0 8px"><tr style="background:#eee"><th style="padding:2px 8px;text-align:left">Shadow</th><th style="padding:2px 8px">Lv</th><th style="padding:2px 8px">HP</th><th style="padding:2px 8px;text-align:left">Floors</th><th style="padding:2px 8px;text-align:left">Weak / resists</th></tr>'+rows.map(r=>'<tr>'+r.map((c,i)=>'<td style="padding:2px 8px;border-top:1px solid #ddd;'+(i==1||i==2?'text-align:right':'')+'">'+esc(c)+'</td>').join('')+'</tr>').join('')+'</table>';
    const intro=['One table per block with the shadows that live there: level, HP, floors and what they are weak or strong against. The rare coin-carrying "Hand" shadows (they run away, one hit usually kills them) are in it too: Wealth Hand in Thebel, Treasure Hand in Arqa, Supreme Hand in Yabbashah, Opulent Hand in Tziah, Luxury Hand in Harabah, Glorious Hand in Adamah. The first five are the ones requests 7, 14, 21, 32 and 47 ask for, and the Glorious Hand is for request 54. The numbers come from a fusion calculator\'s FES data and may not list every shadow <span class="vf">verify</span>; the list marked "Guardians" below is the mini-bosses that block boss floors.'];
    const items=[];
    Object.keys(TS).forEach(b=>{
      const o=TS[b];
      intro.push('<details style="margin:6px 0"><summary style="cursor:pointer"><b>'+(b==='Monad'?'Monad Depths':b)+'</b> ('+o.reg.length+' shadows'+(o.boss.length?', '+o.boss.length+' guardians':'')+')</summary>'+tbl(o.reg)+(o.boss.length?'<div style="font-size:13px"><b>Guardians</b></div>'+tbl(o.boss):'')+'</details>');
      o.boss.forEach(r=>{items.push({id:'gd-'+b.toLowerCase()+'-'+r[0].toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+r[3].replace(/[^0-9]/g,''),t:r[0]+' · floor '+r[3],d:'Level '+r[1]+', HP '+r[2]+'. '+r[4]+'.',gh:b});});
    });
    C.push({id:'shadows',title:'7. Tartarus shadows',intro:intro,items:items});
  }

  // ------------------------------------------------------------------ 7 the answer
  const B=[
   ['Malebolge','Immortal Gigas and Visceral Maya','Gigas is weak to wind, Maya to fire. Kill the Mayas first; Charm on Gigas turns him on his friends.'],
   ['Cocytus','Brilliant Cyclops','No weakness; absorbs all magic. It summons Soul Dancers (weak to ice) that heal it, and uses Mabufula a lot.'],
   ['Caina (first boss)','Death Castle with two helpers','Death Castle only takes damage from Zio. The helpers are weak to ice; take them out first. El Dorado Beast dodges ice.'],
   ['Caina (second boss)','Harem Dancer and two Merciless Mayas','Harem Dancer has no weakness and absorbs ice. The Mayas are weak to wind and cast anti-magic shields; kill them first. The Dancer blocks piercing.'],
   ['Antenora (first boss)','Judgement Sword, Brave Wheel and Ice Raven','Sword is weak to wind, Wheel to ice, Raven to fire, and each dodges its own weakness. A neutral spell that hits everyone is easiest.'],
   ['Antenora (second boss)','Shouting Tiara, Primitive Idol and Wrathful Book','Tiara is weak to ice, Idol to lightning, Book to fire. Use one spell that hits all three.'],
   ['Ptolomea (first boss)','Wondrous Magus, Crying Table and Cowardly Maya','Magus is weak to fire and reflects or absorbs most magic; Table is weak to ice; Maya to fire. They do not absorb lightning or wind.'],
   ['Ptolomea (second boss)','Neo Minotaur','No listed weakness. Beware its strong wind and melee area attacks.'],
   ['Judecca (first boss)','Two Slaughter Drives and Spastic Turret','Drives are weak to lightning but reflect it; the Turret is weak to ice and calls a new Drive when none is left. Drive, Turret, then the last Drive.'],
   ['Judecca (second boss)','Conceited Maya and two Jotuns of Blood','Magic on Maya, physical on the Jotuns, who join once Maya is hurt.'],
   ['Empyrean (first boss)','Rebellious Cyclops and Acheron Seekers','Seekers are weak to fire and lightning. Three area attacks in one turn are the danger.'],
   ['Empyrean (second boss)','Tenjin, Kaiden and Onnen Musha','No weaknesses. Tenjin reflects, Kaiden blocks physical, Onnen absorbs magic. An attack mirror helps against the counters.'],
   ['Empyrean (third boss)','Boss not named in my source','Watch which Persona he switches to and what it casts.'],
   ['Empyrean (last fight before the end)','A fight where only Aigis and Metis take part','Level Metis up beforehand: afterwards you cannot go back and level or equip her. Long critical chains can kill you; save often.'],
   ['Erebus','Erebus (final boss)','Only resists Light and Darkness. It uses strong single and area magic, and Dark Embrace summons a large red eye: deal enough damage and the attack fails and weakens it.']];
  const bi=B.map((x,i)=>({id:'an-b'+(i<9?'0'+(i+1):(i+1)),t:x[0]+' · '+x[1],d:x[2],vf:(i===12||i===13)?'name and details':''}));
  bi.unshift({id:'an-start',t:'Start The Answer',d:'Aigis is the playable character, starting at level 25. There is no school life, no Social Links and no requests; the group does not get tired, so grinding is less interrupted.'});
  bi.push({id:'an-clear',t:'Clear The Answer',d:'About 30 hours.'});
  C.push({id:'answer',title:'8. The Answer (Aigis)',intro:[
    'The Answer picks up after The Journey. It takes place in the <b>Abyss of Time</b>, beneath the dorm, and is much harder than The Journey: the enemies hit hard and one source calls it about twice as hard with about a third of the bosses. Treat each door in the central room like a floor of Tartarus, and grind each area until the enemies start fleeing before the boss. The boss list below follows the order of one walkthrough; open <b>Level, HP and resistances</b> on a boss for numbers from a fusion calculator\'s data (they agree with the walkthrough where I compared them); the area names are Malebolge, Cocytus, Caina, Antenora, Ptolomea, Judecca, Empyrean and Erebus.'],
    items:bi});

  { const ac=C.find(c=>c.id==='answer'); ac.items.forEach(i=>{if(BO[i.id])i.more=BO[i.id];}); }

  C.push({id:'calendar',title:'9. Month by month',intro:[
    'One page per month with what opens, which Full Moon is coming and what to start. It repeats facts from the chapters above, so the same verify flags apply. Tick a month when you have done its list in your game.',
    '<h3>April</h3><ul><li><b>Join a club early.</b> Chariot (kendo), Strength, Star need a sports club; Fortune needs Music, Art or Photography. Whether you can join both kinds is unconfirmed <span class="vf">verify</span>, so check at the club sign-up before choosing.</li><li><b>Magician</b> (Kenji): start any time, he has no requirements.</li><li><b>Apr 20</b> Thebel, the first Tartarus block, opens <span class="vf">verify</span>.</li><li><b>Apr 25</b> Hierophant (Bunkichi) can start: bring the persimmon leaf.</li><li><b>Apr 27</b> Emperor opens: Student Council via Ms. Toriumi; Justice (Chihiro) follows once you are in.</li><li><b>Apr 28</b> Junpei\'s online game starts the Hermit link (Sundays and holidays).</li><li><b>Apr 30</b> request 92 opens: speak to Yukari on the evening of May 2 (errand dates from one source <span class="vf">verify</span>).</li><li>Raise Academics now; it is the slowest stat.</li></ul><h3>May</h3><ul><li><b>May 9</b> Full Moon: Priestess (monorail). Grind Tartarus until enemies are tired first.</li><li><b>May 10</b> second Tartarus block opens <span class="vf">verify</span>.</li><li><b>May 14</b> evening: speak to Junpei (request 93, opens May 10). <b>May 26</b> evening: speak to Mitsuru (request 94). Both due Jun 6 <span class="vf">verify</span>.</li><li>Keep raising Magician, Chariot, Emperor, Hierophant, Hermit and Justice; every link you start early is one you will finish.</li></ul><h3>June</h3><ul><li><b>Jun 8</b> Full Moon: Empress and Emperor.</li><li><b>Mid June</b> Fuuka joins: Priestess link opens (needs a club joined in June and maxed Courage <span class="vf">verify</span>).</li><li><b>Jun 17</b> Fortune (Keisuke) opens; same club leads to Fuuka.</li><li>Requests 95 to 97 open Jun 10, due Jul 5: <b>Jun 16</b> evening Akihiko, <b>Jun 20</b> evening Ikutsuki, <b>Jun 27</b> evening Fuuka <span class="vf">verify</span>.</li><li>Around Hierophant rank 3, Bebe (Temperance) turns up with Bunkichi\'s wallet.</li></ul><h3>July</h3><ul><li><b>Jul 7</b> Full Moon: Hierophant and Lovers.</li><li><b>Jul 10</b> Hanged Man (Maiko) can start <span class="vf">verify</span>; you need a Mad Bull and a Weird Takoyaki.</li><li><b>Jul 24</b> after the beach scene the Lovers link (Yukari) opens; needs maxed Charm <span class="vf">verify</span>.</li><li>Hermit rank 4 or 5 unlocks Devil (President Tanaka) evenings at Paulownia Mall.</li></ul><h3>August</h3><ul><li><b>Aug 6</b> Full Moon: Chariot and Justice.</li><li>After the summer sports competition, Star (Mamoru) opens; needs Courage rank 4.</li><li>Strength rank 4 unlocks Tower (the monk) at Club Escapade; needs Courage "Tough" or better.</li></ul><h3>September</h3><ul><li><b>Sep 5</b> Full Moon: Hermit (Club Escapade).</li><li>Sun (Akinari) needs Hanged Man rank 3; Moon (Nozomi) comes from Magician around rank 3 or 4.</li><li>Keep stats rising: Empress will need maxed Academics and a first place exam.</li></ul><h3>October</h3><ul><li><b>Oct 4</b> Full Moon: Fortune and Strength (Iwatodai Station).</li><li>Check which links are lagging and use free evenings and Sundays on them.</li></ul><h3>November</h3><ul><li><b>Nov 3</b> Full Moon: Jin and Takaya, and Hanged Man (Moonlight Bridge) <span class="vf">verify</span>.</li><li><b>Nov 6</b> the next Tartarus blocks open <span class="vf">verify</span>.</li><li><b>Nov 21</b> Empress (Mitsuru) can progress: maxed Academics, first in class, and the promised reward.</li></ul><h3>December</h3><ul><li>No dated Full Moon in my sources <span class="vf">verify</span>.</li><li>Fool (S.E.E.S.) maxes about two months before the end; maxing it opens Judgment, the last link, which rises as you climb the final block.</li><li>Finish what is open: Tower, Star, Moon, Sun and Empress want attention.</li></ul><h3>January</h3><ul><li><b>Jan 1</b> the final Tartarus block opens <span class="vf">verify</span>.</li><li><b>Jan 7</b> Aeon (Aigis) opens <span class="vf">verify</span> (one source says Jan 8); it must be finished before the end and one date can be missed.</li><li><b>Jan 31</b> final Full Moon: Jin, Takaya and Nyx Avatar. Use up your consumables first.</li></ul>',
    '<h3>Weekday cheat sheet (daytime unless noted)</h3><ul><li><b>Monday</b>: Priestess, Emperor, Lovers, Hanged Man</li><li><b>Tuesday</b>: Magician, Empress, Justice, Fortune, Hanged Man</li><li><b>Wednesday</b>: Emperor, Lovers, Fortune, Strength, Hanged Man</li><li><b>Thursday</b>: Magician, Empress, Justice, Lovers, Fortune, Hanged Man</li><li><b>Friday</b>: Priestess, Magician, Emperor, Hanged Man</li><li><b>Saturday</b>: Priestess, Emperor, Empress, Justice, Lovers, Strength, Hanged Man</li><li><b>Sunday</b>: Hermit, Sun (Hanged Man is closed on Sundays); evenings: Tower, Devil</li></ul><p>Made from the link cards in chapter 3 and only covers links whose days are known; Hierophant, Chariot, Moon, Temperance and Star are not tied to fixed days in my sources <span class="vf">verify</span>.</p>'],
    items:[{id:'mo-04',t:'April done',d:''},{id:'mo-05',t:'May done',d:''},{id:'mo-06',t:'June done',d:''},{id:'mo-07',t:'July done',d:''},{id:'mo-08',t:'August done',d:''},{id:'mo-09',t:'September done',d:''},{id:'mo-10',t:'October done',d:''},{id:'mo-11',t:'November done',d:''},{id:'mo-12',t:'December done',d:''},{id:'mo-01',t:'January done',d:''}]});

  C.push({id:'warnings',title:'10. Don\'t miss these',intro:[
    'The things most likely to cost you a 100% run, gathered from the chapters above. Check this page at the start of each season.',
    '<ul><li><b>Aigis (Aeon)</b> opens in January, must be finished before the game ends, and one of its dates can be missed. Do not leave it to the last week.</li><li><b>Empress (Mitsuru)</b> cannot move before Nov 21 and needs maxed Academics, a first-place exam and the promised reward. Raise Academics from the first week of the game.</li><li><b>Lovers (Yukari)</b> warns you if you go out with other girls; it hurts the link. Needs maxed Charm <span class="vf">verify</span>.</li><li><b>Hierophant (Bunkichi)</b>: always accept his gift, refusing upsets him. Bring the persimmon leaf from the courtyard tree.</li><li><b>Hermit (Maya)</b> and <b>Hanged Man (Maiko)</b> are limited to certain days (Hermit only on Sundays and holidays, Hanged Man never on holidays), so they need a free day each.</li><li><b>Tower (the monk)</b> needs Courage "Tough" or better and Strength rank 4 first; <b>Star (Mamoru)</b> needs Courage rank 4. Raise Courage by the end of summer.</li><li><b>Chariot</b> needs you to join the kendo team early, and it leads to Strength and Star. The sports club is a choice against the culture club <span class="vf">verify</span>.</li><li><b>Fool</b> and <b>Death</b> cannot be raised by you, and <b>Judgment</b> only opens after the Fool link is maxed.</li><li><b>Elizabeth\'s requests</b>: keep one of each item she asks for in your bag, and keep Social Link Personas in your Compendium for the requests that need them (Thor, Siegfried, Odin, Scathach, Metatron, Susano-o, Helel).</li><li><b>Errand requests</b> (92 to 99, plus 81 and 86) are tied to one day each and have a due date, so write the day down when you accept them. The dates I have are on the month pages <span class="vf">verify</span>.</li><li><b>Fusion spell requests (61 to 78)</b> can be done at any time once you hold both Personas, so register them in the Compendium before the game ends.</li><li><b>Before the final boss</b>: the Journey needs a saved clear for The Answer; use all consumables and do the last Tartarus floors beforehand.</li><li><b>The Answer</b>: level Metis before the last fight where only Aigis and Metis take part; you cannot level or equip her afterwards.</li><li><b>Save often and in separate slots</b>: Full Moon bosses and long fusion sessions are easy to regret.</li></ul>'],items:[]});

